local WritingStandMaker = {}
local PRODUCTS = {
    iron_writing_stand = { name = "Železni pisalni mizic", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 160, prestige = 4, happiness = 2, description = "Železni pisalni mizic za pisarje." },
    bronze_writing_stand = { name = "Bronast pisalni mizic", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 390, prestige = 6, happiness = 3, description = "Bronast pisalni mizic za pisarne." },
    silver_writing_stand = { name = "Srebrni pisalni mizic", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 940, prestige = 11, happiness = 4, description = "Srebrni pisalni mizic za plemiške pisarje." },
    gilded_writing_stand = { name = "Pozlačeni pisalni mizic", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2030, prestige = 20, happiness = 5, description = "Pozlačeni pisalni mizic za dvorne pisarje." },
    jewel_set_writing_stand = { name = "Draguljasti pisalni mizic", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4380, prestige = 36, happiness = 7, description = "Draguljasti pisalni mizic za kraljevske pisarje." },
    royal_sovereign_writing_stand = { name = "Kraljevski suvereni pisalni mizic", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9400, prestige = 68, happiness = 13, description = "Suvereni pisalni mizic z biseri za krono." },
}
local BUILDINGS = {
    writingstand_workshop = { name = "Pisalna delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    writingstand_house = { name = "Pisalna hiša", cost = { gold = 1185, wood = 370, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_writingstand_atelier = { name = "Mojstrski pisalni atelje", cost = { gold = 2975, wood = 430, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_writingstand_palace = { name = "Suverena pisalna palača", cost = { gold = 12920, wood = 655, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
WritingStandMaker.ironStock = 12; WritingStandMaker.bronzeStock = 10; WritingStandMaker.woodStock = 18; WritingStandMaker.leatherStock = 10; WritingStandMaker.silverStock = 8; WritingStandMaker.goldStock = 6; WritingStandMaker.jewelStock = 4; WritingStandMaker.pearlStock = 4
WritingStandMaker.productStock = {}; WritingStandMaker.buildings = {}; WritingStandMaker.maker = nil; WritingStandMaker.activeMaking = {}; WritingStandMaker.totalProducts = 0; WritingStandMaker.dayTimer = 0
function WritingStandMaker.init() WritingStandMaker.ironStock=12; WritingStandMaker.bronzeStock=10; WritingStandMaker.woodStock=18; WritingStandMaker.leatherStock=10; WritingStandMaker.silverStock=8; WritingStandMaker.goldStock=6; WritingStandMaker.jewelStock=4; WritingStandMaker.pearlStock=4; WritingStandMaker.productStock={}; WritingStandMaker.buildings={}; WritingStandMaker.maker=nil; WritingStandMaker.activeMaking={}; WritingStandMaker.totalProducts=0; WritingStandMaker.dayTimer=0; print("[WritingStandMaker] Royal Writing Stand Maker System initialized (6 products, 4 buildings)") end
function WritingStandMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WritingStandMaker.maker={name=n or ("Pisar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pisar najet: %s (spretnost: %d)",WritingStandMaker.maker.name,s),"success") end; return true end
function WritingStandMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WritingStandMaker.build(id) local ok,e=WritingStandMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WritingStandMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WritingStandMaker.getQualityBonus() local b=0; for _,bd in ipairs(WritingStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WritingStandMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WritingStandMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WritingStandMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WritingStandMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WritingStandMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WritingStandMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WritingStandMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WritingStandMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WritingStandMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WritingStandMaker.buildings==0 then return false,"Potrebna pisalna delavnica" end; if not WritingStandMaker.maker then return false,"Potreben pisar" end; return true end
function WritingStandMaker.make(pt,qty) qty=qty or 1; local ok,e=WritingStandMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WritingStandMaker.ironStock=WritingStandMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WritingStandMaker.bronzeStock=WritingStandMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WritingStandMaker.woodStock=WritingStandMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WritingStandMaker.leatherStock=WritingStandMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WritingStandMaker.silverStock=WritingStandMaker.silverStock-d.silverCost*qty end; if d.goldCost then WritingStandMaker.goldStock=WritingStandMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WritingStandMaker.jewelStock=WritingStandMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WritingStandMaker.pearlStock=WritingStandMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WritingStandMaker.maker then t=math.max(1,t-math.floor(WritingStandMaker.maker.skill/13)) end; table.insert(WritingStandMaker.activeMaking,{id="writingstand_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WritingStandMaker.completeMaking(m) local q=1.0+(WritingStandMaker.getQualityBonus()/100); if WritingStandMaker.maker then q=q+(WritingStandMaker.maker.skill/140) end; q=math.min(2.5,q); WritingStandMaker.productStock[m.productType]=(WritingStandMaker.productStock[m.productType] or 0)+m.quantity; WritingStandMaker.totalProducts=WritingStandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WritingStandMaker.maker then WritingStandMaker.maker.itemsMade=WritingStandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WritingStandMaker.maker.skill=math.min(100,WritingStandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mizica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"writingstand.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WritingStandMaker.update(dt) if not _G.state then return end; WritingStandMaker.dayTimer=WritingStandMaker.dayTimer+dt; if WritingStandMaker.dayTimer>=30 then WritingStandMaker.dayTimer=0; for i=#WritingStandMaker.activeMaking,1,-1 do local m=WritingStandMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WritingStandMaker.completeMaking(m); table.remove(WritingStandMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WritingStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WritingStandMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WritingStandMaker.getStats() return {ironStock=WritingStandMaker.ironStock,bronzeStock=WritingStandMaker.bronzeStock,woodStock=WritingStandMaker.woodStock,leatherStock=WritingStandMaker.leatherStock,silverStock=WritingStandMaker.silverStock,goldStock=WritingStandMaker.goldStock,jewelStock=WritingStandMaker.jewelStock,pearlStock=WritingStandMaker.pearlStock,productStock=WritingStandMaker.productStock,numBuildings=#WritingStandMaker.buildings,hasMaker=WritingStandMaker.maker~=nil,makerName=WritingStandMaker.maker and WritingStandMaker.maker.name or "—",makerSkill=WritingStandMaker.maker and WritingStandMaker.maker.skill or 0,activeMaking=#WritingStandMaker.activeMaking,totalProducts=WritingStandMaker.totalProducts} end
return WritingStandMaker
